-- 0022 · KIỂM KÊ QUY TRÌNH NGHIỆP VỤ theo ĐỐI TƯỢNG × VÒNG ĐỜI (rà soát toàn dự án) — coverage: DA_CO (bảng+UI+form) · MOT_PHAN (bảng có, UI qua Quản trị DL) · CHUA
alter table processes add column if not exists object_type text, add column if not exists coverage text default 'DA_CO', add column if not exists ui_path text, add column if not exists lifecycle_stage text;
update processes set object_type = case dept_code when 'KTCN' then 'VAT_NUOI' when 'TT' then 'CAY_TRONG' when 'SH' then 'SAN_XUAT' when 'D5' then 'SAN_XUAT' when 'CCU' then 'VAT_TU_KHO' when 'KDM' then 'KHACH_HANG' when 'XNK' then 'KHACH_HANG' when 'DL' then 'KHACH_HANG' when 'TCKT' then 'TAI_CHINH' when 'HCNS' then 'CON_NGUOI' when 'CNTB' then 'THIET_BI_DU_LIEU' when 'QA' then 'CHAT_LUONG' when 'RD' then 'TRI_THUC' when 'MR' then 'TRAI' else 'QUAN_TRI' end where object_type is null;
update processes set ui_path = case code when 'P-KT-01' then '/dan' when 'P-KT-02' then '/thu-y' when 'P-KT-03' then '/thu-y' when 'P-KT-04' then '/dan' when 'P-TT-01' then '/ke-hoach' when 'P-TT-02' then '/canh-tac' when 'P-TT-03' then '/quan-tri?t=lab_samples' when 'P-SH-01' then '/ca' when 'P-SH-02' then '/so-lieu' when 'P-D5-01' then '/ke-hoach' when 'P-D5-02' then '/kho' when 'P-CCU-01' then '/ke-toan' when 'P-CCU-02' then '/kho' when 'P-CCU-03' then '/ca' when 'P-KD-01' then '/ban-hang?tab=crm' when 'P-KD-02' then '/ban-hang' when 'P-KD-03' then '/ban-hang?tab=pos' when 'P-KD-04' then '/ban-hang?tab=nhan-nuoi' when 'P-XNK-01' then '/quan-tri?t=trade_contracts' when 'P-XNK-02' then '/quan-tri?t=import_permits' when 'P-DL-01' then '/du-lich' when 'P-DL-02' then '/du-lich?tab=tiec' when 'P-DL-03' then '/du-lich?tab=tour' when 'P-TC-01' then '/ke-toan' when 'P-TC-02' then '/ke-toan' when 'P-HC-01' then '/nhan-su' when 'P-CN-01' then '/thiet-bi' when 'P-CN-02' then '/canh-bao' when 'P-QA-01' then '/audit' when 'P-QA-02' then '/truy-xuat' when 'P-RD-01' then '/quan-tri?t=rd_trials' when 'P-MR-01' then '/hq?tab=cty' end where ui_path is null;
update processes set coverage='MOT_PHAN' where code in ('P-TT-03','P-XNK-01','P-XNK-02','P-RD-01','P-SH-02','P-QA-01');
