on conflict (code) do update set name=excluded.name, object_type=excluded.object_type, coverage=excluded.coverage, ui_path=excluded.ui_path, inputs=excluded.inputs, outputs=excluded.outputs, tables=excluded.tables;
create or replace view v_process_coverage as select object_type, coverage, count(*) as n from processes where active group by 1,2 order by 1,2;
grant select on v_process_coverage to app_user;
